import 'package:flutter_test/flutter_test.dart'; import 'package:learning_app/features/auth/auth.dart';
void main(){test('remote repository preserves the authenticated session',() async {final repo=RemoteAuthRepository(_Fake());final session=await repo.login('a@test.dev','password');expect(session.user.email,'a@test.dev');});test('notifier coalesces concurrent restores',() async {final remote=_Fake();final notifier=AuthNotifier(RemoteAuthRepository(remote));await Future.wait([notifier.restore(),notifier.restore()]);expect(remote.refreshes,1);});}
class _Fake implements AuthRemote {int refreshes=0;final value=AuthSession(const AuthUser('u','a@test.dev'),'token',DateTime.utc(2026));@override Future<AuthSession> login(String e,String p)async=>value;@override Future<AuthSession> register(String e,String p)async=>value;@override Future<AuthSession?> refresh()async{refreshes++;return value;}@override Future<void> logout()async{}}
